import os
from dataclasses import dataclass

@dataclass
class Job:
    name: str
    retries: int = 3

def run(jobs: list[Job], dry_run: bool = False) -> dict[str, int]:
    results = {}
    for job in jobs:
        if job.retries > 0 and not dry_run:
            results[job.name] = len(job.name) * 2
    return results

